# --- /orders POST ---

def test_create_order_success(client):
    resp = client.post("/orders", json={
        "items": [{"item_id": "traditional-wings", "quantity": 2}],
        "pickup_or_delivery": "delivery",
        "customer_name": "Jane",
    })
